func TestFIFOOrder(t *testing.T) {
	server := newServer()

	// Enqueue multiple jobs
	for i := 1; i <= 3; i++ {
		body := map[string]any{"id": "job" + string(rune('0'+i)), "payload": i}
		b, _ := json.Marshal(body)
